package servicio;
import dao.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;import negocio.*;
public class AuditoriaWebhookMercadoPagoService {private final EventoPagoDAO eventos;public AuditoriaWebhookMercadoPagoService(){this(new EventoPagoDAOMySQL());}public AuditoriaWebhookMercadoPagoService(EventoPagoDAO e){if(e==null)throw new IllegalArgumentException("El DAO de eventos es obligatorio.");eventos=e;}public EventoPago recibir(String requestId,String dataId,String payload,boolean firmaValida){EventoPago e=new EventoPago();e.setProveedor(ProveedorPago.MERCADO_PAGO);e.setEventoExternoId("delivery:"+estable(requestId,dataId,payload));e.setTipo("webhook.delivery");e.setFirmaValida(firmaValida);e.setPayloadHash(hash(payload));e.setPayloadJson(payload);e.setEstadoProcesamiento(firmaValida?EstadoProcesamientoEventoPago.VALIDADO:EstadoProcesamientoEventoPago.ERROR);boolean nuevo=eventos.registrarSiNuevo(e);return nuevo?e:eventos.buscar(ProveedorPago.MERCADO_PAGO.name(),e.getEventoExternoId());}public void procesado(EventoPago e,String detalle){if(e!=null&&e.getId()>0)eventos.marcarProcesado(e.getId(),limitar(detalle));}public void error(EventoPago e,String detalle){if(e!=null&&e.getId()>0)eventos.marcarError(e.getId(),limitar(detalle));}private String estable(String requestId,String dataId,String payload){String base=requestId!=null&&!requestId.isBlank()?requestId:(dataId!=null&&!dataId.isBlank()?"payment:"+dataId:hash(payload));return base.length()<=140?base:hash(base);}private String limitar(String v){String x=v==null?"Sin detalle.":v;return x.length()<=500?x:x.substring(0,500);}private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((v==null?"":v).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}